3: const handleFHIRError = (error: any): string => {
4:   if (error.status === 404) {
5:     return 'The requested resource was not found. Please check the patient ID and try again.';
6:   }
7:   if (error.status === 401) {
8:     return 'Authentication required. Please log in to access this resource.';
9:   }
10:   if (error.status === 403) {
11:     return 'You do not have permission to access this resource.';
12:   }
13:   if (error.status === 400) {
14:     return 'Invalid request. Please check your input and try again.';
15:   }
16:   if (error.status === 422) {
17:     return 'The request could not be processed. Please check your input data.';
18:   }
19:   return error.message || 'An unexpected error occurred. Please try again later.';
20: };
