43: const createBundle = (composition: DischargeSummaryType): DischargeSummaryBundle => {
44:   const entries: DischargeSummaryBundle['entry'] = [];
45:   
46:   // Add the Composition as the first entry
47:   entries.push({
48:     fullUrl: `urn:uuid:${crypto.randomUUID()}`,
49:     resource: composition
50:   });
51: 
52:   // Add referenced resources from sections
53:   composition.section.forEach(section => {
54:     if (section.entry && section.entry.length > 0) {
55:       section.entry.forEach(entry => {
56:         // If the reference is a UUID, use it directly
57:         const isUUID = entry.reference.startsWith('urn:uuid:');
58:         const fullUrl = isUUID ? entry.reference : `urn:uuid:${crypto.randomUUID()}`;
59:         
60:         // Here we assume the referenced resource is already available
61:         // In a real implementation, you might need to fetch or construct these resources
62:         entries.push({
63:           fullUrl,
64:           resource: {
65:             resourceType: entry.type || 'Resource',
66:             id: fullUrl.split(':').pop(),
67:             // Add other resource properties as needed
68:           }
69:         });
70:       });
71:     }
72:   });
73: 
74:   return {
75:     resourceType: 'Bundle',
76:     type: 'document',
77:     timestamp: new Date().toISOString(),
78:     entry: entries
79:   };
80: };
